package simulator

// Real California road geometry so simulated vehicles drive on actual roads instead of straight lines.
// routes.json is generated by tools/routegen/fetch_routes.py (OSRM over OpenStreetMap data, ODbL).

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"math"
	"math/rand"
	"sort"
)

//go:embed routes.json
var routesJSON []byte

type RouteKind string

const (
	RouteHighway  RouteKind = "highway"  // Long freeway corridors (I-5, US-101, CA-99, I-80)
	RouteUrban    RouteKind = "urban"    // Metro loops (Bay Area, LA, OC, San Diego)
	RouteMountain RouteKind = "mountain" // Sierra roads (Lake Tahoe)
)

// Route is a polyline of [lat, lon] points with precomputed cumulative distances
type Route struct {
	Name   string       `json:"name"`
	Kind   RouteKind    `json:"kind"`
	Loop   bool         `json:"loop"` // Ends where it starts: vehicles circulate instead of turning around
	Points [][2]float64 `json:"points"`

	cumKm    []float64 // cumKm[i] = distance from Points[0] to Points[i]
	LengthKm float64
}

var routes = mustLoadRoutes()

func mustLoadRoutes() []*Route {
	var file struct {
		Routes []*Route `json:"routes"`
	}
	if err := json.Unmarshal(routesJSON, &file); err != nil {
		panic(fmt.Sprintf("simulator: invalid embedded routes.json: %v", err))
	}
	for _, r := range file.Routes {
		r.cumKm = make([]float64, len(r.Points))
		for i := 1; i < len(r.Points); i++ {
			r.cumKm[i] = r.cumKm[i-1] + haversineKm(r.Points[i-1], r.Points[i])
		}
		r.LengthKm = r.cumKm[len(r.cumKm)-1]
	}
	return file.Routes
}

// Routes returns every embedded route (read-only)
func Routes() []*Route { return routes }

// RandomRoute picks a route of the given kind (falls back to any route if none match)
func RandomRoute(kind RouteKind) *Route {
	var matches []*Route
	for _, r := range routes {
		if r.Kind == kind {
			matches = append(matches, r)
		}
	}
	if len(matches) == 0 {
		matches = routes
	}
	return matches[rand.Intn(len(matches))]
}

// PositionAt returns the point and compass heading (degrees clockwise from north, in the
// direction of increasing distance) at distKm along the route. distKm is clamped to the route.
func (r *Route) PositionAt(distKm float64) (lat, lon, heading float64) {
	distKm = math.Max(0, math.Min(distKm, r.LengthKm))

	// First point whose cumulative distance is >= distKm; the segment is [i-1, i]
	i := sort.SearchFloat64s(r.cumKm, distKm)
	if i == 0 {
		i = 1
	}
	if i >= len(r.Points) {
		i = len(r.Points) - 1
	}
	a, b := r.Points[i-1], r.Points[i]
	segLen := r.cumKm[i] - r.cumKm[i-1]
	t := 0.0
	if segLen > 0 {
		t = (distKm - r.cumKm[i-1]) / segLen
	}
	lat = a[0] + (b[0]-a[0])*t
	lon = a[1] + (b[1]-a[1])*t
	return lat, lon, bearingDeg(a, b)
}

func haversineKm(a, b [2]float64) float64 {
	const earthRadiusKm = 6371.0
	lat1, lat2 := a[0]*math.Pi/180, b[0]*math.Pi/180
	dLat := lat2 - lat1
	dLon := (b[1] - a[1]) * math.Pi / 180
	h := math.Sin(dLat/2)*math.Sin(dLat/2) + math.Cos(lat1)*math.Cos(lat2)*math.Sin(dLon/2)*math.Sin(dLon/2)
	return 2 * earthRadiusKm * math.Asin(math.Sqrt(h))
}

// bearingDeg is the initial compass bearing from a to b (0 = north, 90 = east)
func bearingDeg(a, b [2]float64) float64 {
	lat1, lat2 := a[0]*math.Pi/180, b[0]*math.Pi/180
	dLon := (b[1] - a[1]) * math.Pi / 180
	y := math.Sin(dLon) * math.Cos(lat2)
	x := math.Cos(lat1)*math.Sin(lat2) - math.Sin(lat1)*math.Cos(lat2)*math.Cos(dLon)
	return math.Mod(math.Atan2(y, x)*180/math.Pi+360, 360)
}
